"use server";

/**
 * Creates a user, their first organization and the owner membership.
 *
 * Owner D. `AuthService.register` performs all three writes in one transaction;
 * this action only turns the result into a session.
 *
 * Must call (do not reimplement): registerSchema, setSessionCookie
 */

import { toActionResult } from "@/lib/errors";
import { setSessionCookie } from "@/lib/session";
import { registerSchema } from "@/schemas/auth";
import { register } from "@/server/services/auth-service";
import { createSessionToken } from "@/server/services/session-service";
import type { ActionResult } from "@/types/api";
import type { SessionPrincipal } from "@/types/member";

export async function registerAction(raw: unknown): Promise<ActionResult<SessionPrincipal>> {
  const parsed = registerSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const { user, org } = await register(parsed.data);
    const { token, expiresAt } = await createSessionToken(user.id);
    await setSessionCookie(token, expiresAt);

    const principal: SessionPrincipal = {
      userId: user.id,
      email: user.email,
      activeOrgId: org.id,
      expiresAt,
    };
    return { ok: true, data: principal, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}
"use server";

/**
 * Signs a user in and sets the session cookie.
 *
 * Owner D. Runs before any tenant is known, so it cannot go through
 * `withAction()` — there is no `Actor` to resolve yet. The rate limit is
 * charged against the anonymous bucket to blunt credential stuffing.
 *
 * Must call (do not reimplement): loginSchema, setSessionCookie,
 * consumeRateLimit
 */

import { ANONYMOUS_ORG_ID } from "@/actions/_lib/permission-resources";
import { RateLimitedError } from "@/actions/_lib/action-errors";
import { toActionResult } from "@/lib/errors";
import { consumeRateLimit } from "@/lib/rate-limit";
import { setSessionCookie } from "@/lib/session";
import { loginSchema } from "@/schemas/auth";
import { login } from "@/server/services/auth-service";
import { resolveSession } from "@/server/services/session-service";
import { UnauthorizedActionError } from "@/actions/_lib/action-errors";
import type { ActionResult } from "@/types/api";
import type { SessionPrincipal } from "@/types/member";

const LOGIN_BUCKET = "auth:login";

export async function loginAction(raw: unknown): Promise<ActionResult<SessionPrincipal>> {
  const parsed = loginSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, LOGIN_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(LOGIN_BUCKET, verdict.resetAt);
    }

    const { token } = await login(parsed.data);
    const principal = await resolveSession(token);
    if (principal === null) {
      throw new UnauthorizedActionError("That sign-in could not be completed.");
    }

    await setSessionCookie(token, principal.expiresAt);
    return { ok: true, data: principal, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}
/**
 * Credential login, registration and password reset. No third-party provider.
 *
 * Must call (do not reimplement): hashPassword, verifyPassword, consumeRateLimit, emit
 *
 * Note: `TaskflowEventMap` has no authentication event and the type is part of
 * the frozen contract, so the declared `emit` is not reachable from here.
 * Registration still publishes `member.joined` — through
 * `OrganizationService.createOrganization`, which owns that membership row.
 */
import {
  hashPassword,
  hashToken,
  randomToken,
  verifyPassword,
} from "@/lib/hash";
import { consumeRateLimit } from "@/lib/rate-limit";
import { slugify } from "@/lib/slug";
import * as resetTokenRepo from "@/server/repositories/_password-reset-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { toIsoTimestamp } from "@/types/common";
import { createOrganization } from "./organization-service";
import { renderEmail, sendEmail } from "./email-service";
import { createSessionToken } from "./session-service";
import type {
  LoginInput,
  PasswordResetConfirmInput,
  PasswordResetRequestInput,
  RegisterInput,
} from "@/schemas/auth";
import type { OrgId, SessionId } from "@/types/common";
import type { User } from "@/types/member";
import type { Organization } from "@/types/organization";

/** Buckets guarding the unauthenticated endpoints. */
const LOGIN_BUCKET = "auth:login";
const RESET_BUCKET = "auth:password-reset";

/**
 * Rate limiting before a session exists has no tenant to charge against, so
 * every unauthenticated attempt is billed to this sentinel bucket.
 */
const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;

/** How long a password-reset link stays usable. */
const RESET_TTL_MS = 60 * 60 * 1000;

/**
 * Registration creates the user and their first workspace in one step — a
 * Taskflow account with no organization cannot do anything, so there is no
 * intermediate state where one exists without the other.
 */
export async function register(
  input: RegisterInput,
): Promise<{ user: User; org: Organization }> {
  const existing = await userRepo.findUserByEmail(input.email);
  if (existing) {
    throw new Error("An account with that email already exists");
  }

  const user = await userRepo.insertUser({
    email: input.email,
    name: input.name,
    passwordHash: await hashPassword(input.password),
  });

  // A reserved or awkward name is handled downstream: `createOrganization`
  // runs the slug through `uniqueSlug()`, which skips reserved words and
  // suffixes collisions.
  const org = await createOrganization(user.id, {
    name: `${input.name}'s workspace`,
    slug: slugify(input.name) || "workspace",
    plan: "free",
  });

  const welcome = await renderEmail("welcome", {
    orgName: org.name,
    recipientName: user.name,
  });
  await sendEmail({ to: user.email, ...welcome });

  return { user, org };
}

/**
 * Credential login. The rate limit is charged before the password is checked,
 * so a brute-force run is throttled whether or not it guesses correctly, and
 * both failure modes return the same message.
 */
export async function login(
  input: LoginInput,
): Promise<{ user: User; token: string }> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, LOGIN_BUCKET);
  if (!verdict.allowed) {
    throw new Error("Too many sign-in attempts; try again shortly");
  }

  const user = await userRepo.findUserByEmail(input.email);
  if (!user) throw new Error("Those credentials did not match");

  const storedHash = await userRepo.findPasswordHash(user.id);
  if (!storedHash || !(await verifyPassword(input.password, storedHash))) {
    throw new Error("Those credentials did not match");
  }

  const { token } = await createSessionToken(user.id);

  return { user, token };
}

export async function logout(sessionId: SessionId): Promise<void> {
  await sessionRepo.revokeSession(sessionId);
}

/**
 * Always resolves, whether or not the address is known — telling an anonymous
 * caller which emails have accounts is an enumeration oracle. Only the token's
 * hash is stored; the raw value exists solely inside the email that carries it.
 */
export async function requestPasswordReset(
  input: PasswordResetRequestInput,
): Promise<void> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
  if (!verdict.allowed) return;

  const user = await userRepo.findUserByEmail(input.email);
  if (!user) return;

  const token = randomToken(32);
  await resetTokenRepo.issueResetToken(
    user.id,
    hashToken(token),
    toIsoTimestamp(new Date(Date.now() + RESET_TTL_MS)),
  );

  const message = await renderEmail("password-reset", {
    recipientName: user.name,
    token,
    expiresInMinutes: RESET_TTL_MS / 60_000,
  });

  await sendEmail({ to: user.email, ...message });
}

/**
 * Consumes a reset token and rewrites the password hash. The token is marked
 * used before the new hash is written, so a replay of the same link cannot
 * overwrite a password the user has since changed again.
 */
export async function confirmPasswordReset(
  input: PasswordResetConfirmInput,
): Promise<User> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
  if (!verdict.allowed) {
    throw new Error("Too many reset attempts; try again shortly");
  }

  const stored = await resetTokenRepo.findLiveResetToken(
    hashToken(input.token),
  );
  if (!stored) throw new Error("That reset link is no longer valid");

  await resetTokenRepo.consumeResetToken(stored.id);
  await userRepo.updatePasswordHash(
    stored.userId,
    await hashPassword(input.password),
  );

  const user = await userRepo.findUserById(stored.userId);
  if (!user) throw new Error("That reset link is no longer valid");

  return user;
}
import { z } from "zod";
import { emailSchema } from "./common";

const passwordSchema = z
  .string()
  .min(12, "use at least 12 characters")
  .max(128)
  .regex(/[a-z]/, "include a lowercase letter")
  .regex(/[A-Z]/, "include an uppercase letter")
  .regex(/[0-9]/, "include a digit");

export const loginSchema = z.object({
  email: emailSchema,
  password: z.string().min(1, "enter your password"),
  rememberMe: z.boolean().default(false),
});

export const registerSchema = z
  .object({
    name: z.string().min(1).max(80),
    email: emailSchema,
    password: passwordSchema,
    confirmPassword: z.string(),
    acceptTerms: z.literal(true, "you must accept the terms"),
  })
  .refine((data) => data.password === data.confirmPassword, {
    message: "passwords do not match",
    path: ["confirmPassword"],
  });

export const passwordResetRequestSchema = z.object({
  email: emailSchema,
});

export const passwordResetConfirmSchema = z
  .object({
    token: z.string().min(16),
    password: passwordSchema,
    confirmPassword: z.string(),
  })
  .refine((data) => data.password === data.confirmPassword, {
    message: "passwords do not match",
    path: ["confirmPassword"],
  });

export type LoginInput = z.infer<typeof loginSchema>;
export type RegisterInput = z.infer<typeof registerSchema>;
export type PasswordResetRequestInput = z.infer<
  typeof passwordResetRequestSchema
>;
export type PasswordResetConfirmInput = z.infer<
  typeof passwordResetConfirmSchema
>;
/**
 * Thin wrappers turning a Zod parse into an `AppErrorShape` without throwing.
 *
 * Server Actions parse `FormData` with `safeParse()` so a validation failure
 * comes back as a `Result` the form layer can render; pages parse
 * `searchParams` with `parseSearchParams()`, which never fails because a
 * hand-edited URL must not produce an error boundary.
 */
import type { Result } from "@/types/api";
import { err, ok } from "@/types/api";
import type { ZodType } from "zod";
import { fieldErrorsFromZod } from "./errors";

/** Parses without throwing; failures carry Zod's field errors verbatim. */
export function safeParse<TSchema extends ZodType>(
  schema: TSchema,
  raw: unknown,
): Result<unknown> {
  const parsed = schema.safeParse(raw);
  if (parsed.success) return ok<unknown>(parsed.data);

  return err<unknown>({
    code: "validation_failed",
    message: "Please correct the highlighted fields.",
    fieldErrors: fieldErrorsFromZod(parsed.error),
  });
}

/**
 * Normalises a Next `searchParams` record (values may be repeated, and are
 * always strings) and parses it. Because the pagination and sort schemas use
 * `.catch()` defaults, a malformed query string degrades to the defaults
 * rather than failing the render; a schema without catches will still throw,
 * which is the correct signal that the route needs one.
 */
export function parseSearchParams<TSchema extends ZodType>(
  schema: TSchema,
  raw: Readonly<Record<string, string | string[] | undefined>>,
): unknown {
  const normalized: Record<string, string | string[]> = {};
  for (const [key, value] of Object.entries(raw)) {
    if (value === undefined) continue;
    normalized[key] = value;
  }

  return schema.parse(normalized);
}
/**
 * Token-bucket limiter applied to invites, comments, search and password
 * resets.
 *
 * Buckets are keyed by `(orgId, bucketKey)` and held in process — Taskflow
 * runs single-writer, and the corpus has no external cache. Capacity scales
 * with the org's plan through `getPlanLimits()`, so a growth org is not held
 * to a free org's ceiling; the per-bucket shape below is the base rate.
 */
import { getPlanLimits } from "@/config/plan-limits";
import type { PlanId } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

export type RateLimitVerdict = {
  allowed: boolean;
  remaining: number;
  resetAt: IsoTimestamp;
};

export type RateLimitConfig = { capacity: number; refillPerMinute: number };

export const RATE_LIMIT_BUCKETS: Readonly<Record<string, RateLimitConfig>> = {
  "member:invite": { capacity: 20, refillPerMinute: 2 },
  "comment:create": { capacity: 60, refillPerMinute: 20 },
  "issue:create": { capacity: 60, refillPerMinute: 20 },
  "search:query": { capacity: 120, refillPerMinute: 60 },
  "auth:password-reset": { capacity: 5, refillPerMinute: 1 },
  "webhook:deliver": { capacity: 100, refillPerMinute: 50 },
};

/** Applied to any key not in the table above. */
const DEFAULT_BUCKET: RateLimitConfig = { capacity: 30, refillPerMinute: 10 };

type BucketState = { tokens: number; updatedAt: number };

const buckets = new Map<string, BucketState>();

/** Plan-aware org context; services set this when they know the org's plan. */
const planByOrg = new Map<OrgId, PlanId>();

/** Records an org's plan so subsequent bucket sizes scale with its quota. */
export function setOrgPlan(orgId: OrgId, plan: PlanId): void {
  planByOrg.set(orgId, plan);
}

export function getBucketConfig(bucketKey: string): RateLimitConfig {
  return RATE_LIMIT_BUCKETS[bucketKey] ?? DEFAULT_BUCKET;
}

/**
 * Scales the base bucket by the org's hourly API allowance, so the limiter
 * and the plan catalogue can never drift apart: the plan is the source of
 * the ceiling, this table only sets the relative shape.
 */
function configFor(orgId: OrgId, bucketKey: string): RateLimitConfig {
  const base = getBucketConfig(bucketKey);
  const plan = planByOrg.get(orgId) ?? "free";
  const hourly = getPlanLimits(plan).apiRequestsPerHour;
  const factor = Number.isFinite(hourly) ? Math.max(1, hourly / 100) : 100;

  return {
    capacity: Math.min(base.capacity * factor, base.capacity * 100),
    refillPerMinute: Math.min(
      base.refillPerMinute * factor,
      base.refillPerMinute * 100,
    ),
  };
}

/**
 * Spends `cost` tokens from the bucket, refilling first for the elapsed time.
 * Async because the production limiter is expected to move behind a store —
 * every call site already awaits it.
 */
export async function consumeRateLimit(
  orgId: OrgId,
  bucketKey: string,
  cost = 1,
): Promise<RateLimitVerdict> {
  const config = configFor(orgId, bucketKey);
  const key = `${orgId}:${bucketKey}`;
  const nowMs = Date.now();

  const state = buckets.get(key) ?? { tokens: config.capacity, updatedAt: nowMs };
  const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;
  const tokens = Math.min(
    config.capacity,
    state.tokens + elapsedMinutes * config.refillPerMinute,
  );

  const allowed = tokens >= cost;
  const remaining = allowed ? tokens - cost : tokens;
  buckets.set(key, { tokens: remaining, updatedAt: nowMs });

  const deficit = allowed ? config.capacity - remaining : cost - remaining;
  const minutesToReset =
    config.refillPerMinute > 0 ? Math.max(0, deficit) / config.refillPerMinute : 0;

  return {
    allowed,
    remaining: Math.floor(remaining),
    resetAt: toIsoTimestamp(new Date(nowMs + minutesToReset * 60_000)),
  };
}

/** Test-only: drops every bucket and org plan association. */
export function resetRateLimits(): void {
  buckets.clear();
  planByOrg.clear();
}
/**
 * Slug generation and validation, shared by organization creation, project
 * creation and the "is this slug free?" checks in both the Zod schemas and the
 * repositories. One implementation so the client preview and the server
 * insertion can never disagree.
 */

export const SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

export const SLUG_MIN_LENGTH = 2;
export const SLUG_MAX_LENGTH = 48;

/** Slugs the router or marketing pages already claim. */
export const RESERVED_SLUGS: readonly string[] = [
  "admin",
  "api",
  "auth",
  "billing",
  "blog",
  "changelog",
  "dashboard",
  "docs",
  "help",
  "login",
  "logout",
  "new",
  "pricing",
  "register",
  "settings",
  "static",
  "support",
  "taskflow",
  "www",
];

/** Lowercases, strips diacritics and punctuation, collapses to `a-z0-9-`. */
export function slugify(input: string): string {
  return input
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, SLUG_MAX_LENGTH)
    .replace(/-+$/g, "");
}

export function isValidSlug(value: string): boolean {
  return (
    value.length >= SLUG_MIN_LENGTH &&
    value.length <= SLUG_MAX_LENGTH &&
    SLUG_PATTERN.test(value)
  );
}

export function isReservedSlug(value: string): boolean {
  return RESERVED_SLUGS.includes(value);
}

export class InvalidSlugError extends Error {
  readonly code = "validation_failed" as const;

  constructor(readonly value: string, readonly reason: string) {
    super(`Invalid slug "${value}": ${reason}`);
    this.name = "InvalidSlugError";
  }
}

export function assertValidSlug(value: string): void {
  if (!isValidSlug(value)) {
    throw new InvalidSlugError(value, "must match ^[a-z0-9]+(-[a-z0-9]+)*$");
  }
  if (isReservedSlug(value)) {
    throw new InvalidSlugError(value, "is reserved");
  }
}

/**
 * Derives a slug from `input` that collides with nothing in `taken`, by
 * appending `-2`, `-3`, … Repositories pass their existing slug set in.
 */
export function uniqueSlug(input: string, taken: Iterable<string>): string {
  const base = slugify(input) || "item";
  const used = new Set(taken);
  if (!used.has(base) && !isReservedSlug(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const candidate = `${base.slice(0, SLUG_MAX_LENGTH - 5)}-${suffix}`;
    if (!used.has(candidate) && !isReservedSlug(candidate)) return candidate;
  }
  throw new InvalidSlugError(base, "exhausted unique suffixes");
}

/** Project keys are the short uppercase prefix shown on issue numbers (TF-12). */
export function projectKeyFromName(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  const letters =
    words.length >= 2
      ? words.slice(0, 3).map((w) => w[0] ?? "").join("")
      : (words[0] ?? "task").slice(0, 3);
  return letters.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 4) || "TASK";
}
/**
 * Maps thrown domain errors onto `AppErrorShape`.
 *
 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
 * `ZodError`); Server Actions and Route Handlers never propagate those to the
 * client. Everything funnels through `toAppError()` so one thrown class maps
 * to exactly one `ErrorCode` and one HTTP status, app-wide.
 */
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
import { ZodError, type ZodIssue } from "zod";

export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
  unauthorized: 401,
  forbidden: 403,
  not_found: 404,
  validation_failed: 422,
  conflict: 409,
  rate_limited: 429,
  plan_limit_exceeded: 402,
  tenant_scope_violation: 403,
  internal_error: 500,
};

/** True for the error classes this module knows how to translate faithfully. */
export function isDomainError(error: unknown): boolean {
  return (
    error instanceof PermissionDeniedError ||
    error instanceof TenantScopeError ||
    error instanceof FeatureDisabledError ||
    error instanceof AlreadyArchivedError ||
    error instanceof InvalidSlugError ||
    error instanceof ZodError
  );
}

/** Collapses a `ZodError` into the `field → messages` map forms consume. */
export function fieldErrorsFromZod(
  error: ZodError,
): Readonly<Record<string, readonly string[]>> {
  const fields: Record<string, string[]> = {};
  for (const issue of error.issues as readonly ZodIssue[]) {
    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
    (fields[key] ??= []).push(issue.message);
  }
  return fields;
}

export function toAppError(error: unknown): AppErrorShape {
  if (error instanceof ZodError) {
    return {
      code: "validation_failed",
      message: "Please correct the highlighted fields.",
      fieldErrors: fieldErrorsFromZod(error),
    };
  }

  if (error instanceof PermissionDeniedError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: {
        action: error.action,
        resourceKind: error.decision.resourceKind,
        reason: error.decision.reason,
      },
    };
  }

  if (error instanceof TenantScopeError) {
    return {
      code: "tenant_scope_violation",
      message: "That resource belongs to a different organization.",
      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
    };
  }

  if (error instanceof FeatureDisabledError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: { flag: error.flag },
    };
  }

  if (error instanceof AlreadyArchivedError) {
    return {
      code: "conflict",
      message: error.message,
      meta: { entity: error.entity, id: error.id },
    };
  }

  if (error instanceof InvalidSlugError) {
    return {
      code: "validation_failed",
      message: error.message,
      fieldErrors: { slug: [error.message] },
      meta: { value: error.value },
    };
  }

  return {
    code: "internal_error",
    message:
      error instanceof Error ? error.message : "Something went wrong. Try again.",
  };
}

/** The failure envelope a Server Action returns instead of throwing. */
export function toActionResult(error: unknown): ActionResult<never> {
  return {
    ok: false,
    error: toAppError(error),
    submittedAt: new Date().toISOString(),
  };
}
/**
 * Error types raised by Server Actions that are *expected* failures rather
 * than bugs. Each one carries the `ErrorCode` that `toAppError()` maps into
 * the `AppErrorShape` the client form layer renders, mirroring the convention
 * already used by `PermissionDeniedError` and `TenantScopeError`.
 *
 * These live in `src/actions/_lib` because only the action layer produces
 * them — services throw their own domain errors, and repositories throw none.
 */

import type { LimitedResource } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";
import type { PermissionAction } from "@/types/permission";

/** No session at all, or a session whose active organization is gone. */
export class UnauthorizedActionError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedActionError";
  }
}

/**
 * `can()` returned false. Distinct from `PermissionDeniedError` (thrown by
 * `assertCan()` inside services) only in that the action layer already knows
 * the action name and does not need the full `PermissionDecision`.
 */
export class ForbiddenActionError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly action: PermissionAction) {
    super(`Permission denied: ${action}`);
    this.name = "ForbiddenActionError";
  }
}

/** A plan quota from `@/config/plan-limits` would be breached. */
export class PlanLimitError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly resource: LimitedResource,
    readonly limit: number,
    readonly used: number,
  ) {
    super(`Plan limit reached for ${resource}: ${used}/${limit}`);
    this.name = "PlanLimitError";
  }
}

/** The token bucket in `@/lib/rate-limit` refused the request. */
export class RateLimitedError extends Error {
  readonly code = "rate_limited" as const;

  constructor(
    readonly bucketKey: string,
    readonly resetAt: IsoTimestamp,
  ) {
    super(`Rate limit exceeded for ${bucketKey}; retry after ${resetAt}`);
    this.name = "RateLimitedError";
  }
}

/** A feature flag that gates the whole action is off for this organization. */
export class FeatureUnavailableError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: string) {
    super(`Feature not available: ${flag}`);
    this.name = "FeatureUnavailableError";
  }
}

/** The row the action addresses does not exist inside the actor's tenant. */
export class ActionNotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(readonly what: string) {
    super(`Not found: ${what}`);
    this.name = "ActionNotFoundError";
  }
}
/**
